import sys,os
sys.path.insert(0,os.path.dirname(os.path.abspath(__file__)))
from helper import setup,add,addm,run
setup('R 300.13','Lokführer, Ziff.')
F="Diesen Vorschriften sind unterstellt: LF (direktes und indirektes Führen), LF in Ausbildung, Führergehilfe."
addm("1","Geltungsbereich","Wer ist den Vorschriften gemäss § unterstellt (Mehrfachauswahl).",["LF (direktes und indirektes Führen)","LF in Ausbildung","Führergehilfe"],["FDL","ZBE","RL"],F)
F="Der LF ist für die vorschriftgemässe und zweckmässige Ausübung der Arbeit verantwortlich. Der LF ist für die Arbeitsverrichtung des zugeteilten LF in Ausbildung je nach dessen Ausbildungsstand mitverantwortlich. Der LF in Ausbildung ist entsprechend des Ausbildungsstands mitverantwortlich. Der LF ist für die Arbeitsverrichtung des zugeteilten Führergehilfen mitverantwortlich."
add("2.1.1","Verantwortung LF","Wofür ist der LF gemäss § verantwortlich?","Für die vorschriftgemässe und zweckmässige Ausübung der Arbeit.",["Nur für die Bedienung des Triebfahrzeugs.","Nur für die Einhaltung des Fahrplans.","Nur für die Sicherheit der Reisenden."],F)
addm("2.1.1","Mitverantwortung LF","Für wessen Arbeitsverrichtung ist der LF gemäss § mitverantwortlich (Mehrfachauswahl).",["Des zugeteilten LF in Ausbildung (je nach Ausbildungsstand)","Des zugeteilten Führergehilfen"],["Des ZBE","Des zuständigen FDL"],F)
F="Bei der Dienstübergabe hat der abtretende LF dem übernehmenden LF allfällige noch nicht ausgeführte quittungspflichtige Befehle zu übermitteln. Ebenso weist der abtretende LF den übernehmenden LF auf noch nicht ausgeführte protokollpflichtige Befehle hin und macht gegebenenfalls auf ausserordentliche Situationen an Fahrzeugen und Anlagen aufmerksam. Nach der Übermittlung bzw. Bekanntgabe dieser Befehle geht die Verantwortung vom abtretenden an den übernehmenden LF über."
add("2.1.2","Dienstübergabe quittungspflichtig","Was hat der abtretende LF gemäss § dem übernehmenden LF bei noch nicht ausgeführten quittungspflichtigen Befehlen zu tun?","Sie zu übermitteln.",["Sie nur zu erwähnen.","Sie dem FDL zurückzugeben.","Sie zu widerrufen."],F)
add("2.1.2","Dienstübergabe protokollpflichtig","Was hat der abtretende LF gemäss § bei noch nicht ausgeführten protokollpflichtigen Befehlen zu tun?","Den übernehmenden LF darauf hinzuweisen.",["Sie dem übernehmenden LF neu zu übermitteln.","Sie zu widerrufen.","Sie dem FDL zurückzugeben."],F)
add("2.1.2","Übergang Verantwortung","Wann geht die Verantwortung gemäss § vom abtretenden an den übernehmenden LF über?","Nach der Übermittlung bzw. Bekanntgabe der Befehle.",["Beim Betreten des Führerstandes.","Bei Ankunft im Bahnhof.","Beim Unterschreiben des Dienstplans."],F)
F="Bei Vorspann-, Schiebe- und Zwischendienst sowie bei vereinigter Führung von Zügen ist grundsätzlich der vorderste LF für die Zugführung verantwortlich. Die LF nachfolgender Triebfahrzeuge sind im Rahmen ihrer Möglichkeiten mitverantwortlich, insbesondere für die Beachtung der Geschwindigkeit."
add("2.1.3","Mehrere Triebfahrzeuge Zugführung","Wer ist bei Vorspann-, Schiebe- und Zwischendienst sowie bei vereinigter Führung von Zügen gemäss § grundsätzlich für die Zugführung verantwortlich?","Der vorderste LF.",["Der hinterste LF.","Der dienstälteste LF.","Alle LF gleichermassen."],F)
add("2.1.3","Nachfolgende LF","Wofür sind die LF nachfolgender Triebfahrzeuge gemäss § im Rahmen ihrer Möglichkeiten insbesondere mitverantwortlich?","Für die Beachtung der Geschwindigkeit.",["Für die Beachtung der Signale.","Für die Kommunikation mit dem FDL.","Für die Bremsprobe."],F)
F="Weisungsbefugnis gegenüber dem LF haben im Rahmen der fahrdienstlichen Prozesse der zuständige FDL; der RL, allenfalls der RA; der ZBE. Der LF hat gegenüber dem LF in Ausbildung sowie gegenüber dem Führergehilfen Weisungsbefugnis."
addm("2.2.1","Weisungsbefugnis gegenüber LF","Wer hat im Rahmen der fahrdienstlichen Prozesse gemäss § Weisungsbefugnis gegenüber dem LF (Mehrfachauswahl).",["Der zuständige FDL","Der RL, allenfalls der RA","Der ZBE"],["Der Führergehilfe","Der LF in Ausbildung"],F)
addm("2.2.1","Weisungsbefugnis des LF","Gegenüber wem hat der LF gemäss § Weisungsbefugnis (Mehrfachauswahl).",["Gegenüber dem LF in Ausbildung","Gegenüber dem Führergehilfen"],["Gegenüber dem FDL","Gegenüber dem ZBE"],F)
add("2.2.2","Technische Anordnungen","Wer ist gemäss § für technische Anordnungen bei Störungen oder Schäden an Triebfahrzeugen allein zuständig, wenn keine sachkundige Person zur Verfügung steht?","Der LF.",["Der FDL.","Der ZBE.","Der RL."],"Steht keine sachkundige Person zur Verfügung, ist für technische Anordnungen bei Störungen oder Schäden an Triebfahrzeugen der LF allein zuständig.")
F="Fühlt sich der LF nicht mehr in der Lage, die Arbeit weiterzuführen, hat der LF anzuhalten und entweder einen Ersatz anzufordern oder für die Weiterfahrt eine geeignete Person eines EBU zu verlangen. Diese Person ist zu instruieren, wie der Zug im Notfall anzuhalten ist."
add("2.3","Dienstunfähigkeit","Was hat der LF gemäss § zu tun, wenn er sich nicht mehr in der Lage fühlt, die Arbeit weiterzuführen?","Anhalten und einen Ersatz anfordern oder für die Weiterfahrt eine geeignete Person eines EBU verlangen.",["Mit Fahrt auf Sicht bis zum nächsten Bahnhof weiterfahren.","Den Zug mit erhöhter Vorsicht ins Depot führen.","Die Fahrt dem FDL melden und weiterfahren."],F)
add("2.3","Instruktion Person","Worüber ist die geeignete Person eines EBU gemäss § zu instruieren, die für die Weiterfahrt verlangt wird?","Wie der Zug im Notfall anzuhalten ist.",["Wie die Zugbeeinflussung zu bedienen ist.","Wie die Strecke zu befahren ist.","Wie die Reisenden zu informieren sind."],F)
add("2.4","Ausrüstung LF","Was hat der LF gemäss § während der Arbeit mitzuführen?","Die für die sichere Ausübung der Arbeit notwendigen Dokumente und Hilfsmittel.",["Nur den Fahrausweis des EVU.","Nur das Mobiltelefon.","Alle Dokumente des Depots."],"Der LF hat während der Arbeit die für die sichere Ausübung der Arbeit notwendigen Dokumente und Hilfsmittel mitzuführen.")
add("2.5.1","Mindestfahrpraxis","Welche Mindestfahrpraxis hat der LF gemäss § zu erfüllen?","Gemäss der Verordnung des UVEK über die Zulassung zum Führen von Triebfahrzeugen der Eisenbahnen.",["Gemäss den Betriebsvorschriften des EVU.","Gemäss den Weisungen des FDL.","Gemäss der Verordnung des BAV."],"Der LF hat eine Mindestfahrpraxis gemäss der Verordnung des UVEK über die Zulassung zum Führen von Triebfahrzeugen der Eisenbahnen zu erfüllen.")
F="Der LF ist berechtigt, diejenigen Strecken und Bahnhöfe zu befahren, für die der LF die nötigen Kenntnisse erlangt hat. Zum Erlangen der Kenntnisse ist ein viermaliges Befahren in jeder Richtung erforderlich, nach Möglichkeit einmal bei Dunkelheit. Wenn der LF während drei aufeinanderfolgenden Jahren eine Strecke oder einen Bahnhof nicht mehr befahren hat, sind die Kenntnisse als ungenügend zu betrachten und aufzufrischen. Der LF ist mitverantwortlich für die Sicherstellung des Kenntnisstandes. Zum Auffrischen der Kenntnisse ist mindestens ein einmaliges Befahren in jeder Richtung erforderlich. Zum Erlangen und Auffrischen der Strecken- und Bahnhofkenntnisse sind alternative Ausbildungsmethoden zulässig. Zum Beispiel können Videos verwendet werden, welche die Strecke oder den Bahnhof aus Sicht des LF zeigen. Der LF ist berechtigt, unvertraute Strecken und Bahnhöfe ohne Strecken- und Bahnhofkenntnisse zu befahren, wenn der LF dabei von einem streckenkundigen LF pilotiert wird. Bei Betriebsstörungen ist es dem LF erlaubt, unvertraute Strecken und Bahnhöfe auf eigene Verantwortung zu befahren. Der LF muss aber im Besitze der nötigen Streckentabellen sein und die den Strecken und Bahnhöfen zugehörigen Ausführungsbestimmungen kennen und anwenden können. Die Fahrweise ist der gegebenen Situation anzupassen. Die EVU geben die Strecken und Bahnhöfe bekannt, die bei ungenügenden Strecken- und Bahnhofkenntnissen nicht befahren werden dürfen."
add("2.5.2","Erlangen Kenntnisse","Wie oft ist zum Erlangen der Strecken- und Bahnhofkenntnisse gemäss § ein Befahren in jeder Richtung erforderlich?","Viermal, nach Möglichkeit einmal bei Dunkelheit.",["Zweimal.","Dreimal.","Fünfmal."],F)
add("2.5.2","Ungenügende Kenntnisse","Nach wie vielen aufeinanderfolgenden Jahren ohne Befahren sind die Strecken- oder Bahnhofkenntnisse gemäss § als ungenügend zu betrachten?","Nach drei Jahren.",["Nach einem Jahr.","Nach zwei Jahren.","Nach fünf Jahren."],F)
add("2.5.2","Auffrischen Kenntnisse","Wie oft ist zum Auffrischen der Kenntnisse gemäss § mindestens ein Befahren in jeder Richtung erforderlich?","Mindestens einmal.",["Mindestens zweimal.","Mindestens viermal.","Mindestens dreimal."],F)
add("2.5.2","Alternative Methoden","Was ist gemäss § zum Erlangen und Auffrischen der Strecken- und Bahnhofkenntnisse zusätzlich zulässig?","Alternative Ausbildungsmethoden, z.B. Videos aus Sicht des LF.",["Nur Streckentabellen studieren.","Nur Mitfahrt als Passagier.","Keine alternativen Methoden."],F)
add("2.5.2","Unvertraute Strecken Pilot","Unter welcher Bedingung darf der LF gemäss § unvertraute Strecken und Bahnhöfe ohne Kenntnisse befahren?","Wenn er von einem streckenkundigen LF pilotiert wird.",["Wenn er die Streckentabelle bei sich hat.","Wenn der FDL zugestimmt hat.","Wenn er die Strecke bei Tageslicht befährt."],F)
addm("2.5.2","Betriebsstörungen unvertraut","Was gilt gemäss § für das Befahren unvertrauter Strecken bei Betriebsstörungen (Mehrfachauswahl).",["Der LF darf auf eigene Verantwortung fahren","Der LF muss im Besitz der nötigen Streckentabellen sein","Der LF muss die zugehörigen Ausführungsbestimmungen kennen und anwenden können","Die Fahrweise ist der gegebenen Situation anzupassen"],["Der LF muss von einem streckenkundigen LF pilotiert werden","Der LF darf nur mit Zustimmung des EVU fahren"],F)
add("2.5.2","Nicht befahrbare Strecken","Wer gibt gemäss § die Strecken und Bahnhöfe bekannt, die bei ungenügenden Kenntnissen nicht befahren werden dürfen?","Die EVU.",["Die ISB.","Der FDL.","Das BAV."],F)
add("2.5.3","Fahrzeugkenntnisse","Nach wie vielen aufeinanderfolgenden Jahren ohne Bedienung eines Triebfahrzeugtyps sind die Fahrzeugkenntnisse gemäss § als ungenügend zu betrachten?","Nach fünf Jahren.",["Nach einem Jahr.","Nach drei Jahren.","Nach zehn Jahren."],"Wenn der LF während fünf aufeinanderfolgenden Jahren einen bestimmten oder in der Bedienung ähnlichen Typ eines Triebfahrzeuges nie bedient hat, sind die Kenntnisse für diesen als ungenügend zu betrachten und aufzufrischen.")
add("3.1.1","Kontrolle Sicherheitseinrichtungen","Wie oft hat der LF das richtige Funktionieren der Sicherheitseinrichtungen auf den Triebfahrzeugen und Steuerwagen gemäss § mindestens zu prüfen?","Täglich mindestens einmal; das Ergebnis ist zu protokollieren.",["Bei jedem Wechsel des Führerstandes.","Wöchentlich einmal.","Nur bei Verdacht auf eine Störung."],"Der LF hat das richtige Funktionieren der Sicherheitseinrichtungen auf den Triebfahrzeugen und Steuerwagen täglich mindestens einmal nach den Vorgaben des EVU zu prüfen. Das Ergebnis ist zu protokollieren.")
add("3.1.2","Kontrolle Registriergeräte","Wann hat der LF die Aufzeichnungsgeräte für die Geschwindigkeit und die Zugbeeinflussung gemäss § zu kontrollieren?","Bei Inbetriebnahme sowie nach Möglichkeit auch während des Dienstes.",["Nur bei Inbetriebnahme.","Nur nach Dienstende.","Nur auf Verlangen des FDL."],"Der LF hat das ordnungsgemässe Funktionieren der Aufzeichnungsgeräte für die Geschwindigkeit und für die Zugbeeinflussung bei Inbetriebnahme sowie nach Möglichkeit auch während des Dienstes nach den Vorgaben des EVU zu kontrollieren.")
F="Auf Triebfahrzeugen mit zwei getrennten Führerständen ist, ausgenommen bei Störungen, der in der Fahrrichtung vordere Führerstand zu bedienen. Indirekt geführte Rangierfahrten dürfen vom hinteren Führerstand aus geführt werden, direkt geführte Rangierfahrten nur über übersichtliche Fahrwege."
add("3.2.1","Vorderer Führerstand","Welcher Führerstand ist auf Triebfahrzeugen mit zwei getrennten Führerständen gemäss § ausgenommen bei Störungen zu bedienen?","Der in der Fahrrichtung vordere Führerstand.",["Der in der Fahrrichtung hintere Führerstand.","Der Führerstand nach Wahl des LF.","Beide Führerstände gleichzeitig."],F)
add("3.2.1","Rangierfahrten hinterer Führerstand","Wann dürfen Rangierfahrten gemäss § vom hinteren Führerstand aus geführt werden?","Indirekt geführte Rangierfahrten immer, direkt geführte nur über übersichtliche Fahrwege.",["Alle Rangierfahrten ohne Einschränkung.","Nur indirekt geführte Rangierfahrten über übersichtliche Fahrwege.","Keine Rangierfahrten."],F)
add("3.2.2","Dokumente im Führerstand","Wo müssen die während der Fahrt benötigten Unterlagen wie Fahrordnungen, Streckentabellen und Befehle gemäss § vorhanden sein?","An einem geeigneten Ort im Führerstand gut sichtbar.",["In der Tasche des LF.","Im Gepäckabteil.","Beim ZBE."],"Die während der Fahrt benötigten Unterlagen, wie Fahrordnungen, Streckentabellen und Befehle müssen an einem geeigneten Ort im Führerstand gut sichtbar vorhanden sein.")
F="Nebst dem für die Bedienung eingeteilten LF dürfen sich im Triebfahrzeug während der Fahrt nur Personen aufhalten, welche eine Berechtigung haben und sich darüber ausweisen können, ausgenommen davon sind die den Reisenden zugänglichen Abteile von Trieb- und Steuerwagen sowie von Triebzügen. Das EVU regelt die Höchstzahl der Personen, welche sich während der Fahrt im bedienten Führerstand aufhalten dürfen. Prüfungsexperten und Ausbildungspersonal können unter Beachtung des nötigen Fluchtwegs davon abweichend entscheiden. Sind die Führerstände von Trieb- oder Steuerwagen für die Beförderung von Reisenden eingerichtet, kann das EVU entsprechende Vorschriften erlassen."
add("3.2.3","Zutritt Triebfahrzeug","Welche Personen dürfen sich gemäss § nebst dem eingeteilten LF während der Fahrt im Triebfahrzeug aufhalten?","Nur Personen, die eine Berechtigung haben und sich darüber ausweisen können.",["Alle Mitarbeitenden des EVU.","Nur Vorgesetzte.","Alle Personen mit Fahrausweis."],F)
add("3.2.3","Höchstzahl Personen","Wer regelt gemäss § die Höchstzahl der Personen im bedienten Führerstand während der Fahrt?","Das EVU.",["Die ISB.","Der LF.","Das BAV."],F)
add("3.2.3","Prüfungsexperten","Unter welcher Bedingung können Prüfungsexperten und Ausbildungspersonal gemäss § von der Höchstzahl abweichend entscheiden?","Unter Beachtung des nötigen Fluchtwegs.",["Mit Zustimmung des FDL.","Nur bei Ausbildungsfahrten bei Nacht.","Nur mit schriftlicher Bewilligung des BAV."],F)
F="Befinden sich nebst dem eingeteilten LF zusätzlich ein Vorgesetzter, ein LF in Ausbildung, ein Führergehilfe oder ein weiterer LF im Führerstand, haben sich diese die Stellung der Signale zu melden. Das Melden der Signale lautet grundsätzlich wie folgt: Zugsignal: Warnung oder Halt «zu»; Ankündigung Freie Fahrt oder Freie Fahrt «offen»; Geschwindigkeits-Ankündigung oder Geschwindigkeits-Ausführung «offen» und die signalisierte Geschwindigkeit bzw. die in der Streckentabelle vorgeschriebene abweichende Geschwindigkeit; Kurze Fahrt «kurze Fahrt». Beim Einfahrsignal ist zusätzlich zur Stellung der Name des betreffenden Bahnhofs zu melden. Zwergsignal: Halt «zu»; Fahrt «gerade offen»; Fahrt mit Vorsicht «schräg offen». Rangiersignal: Halt für Rangierbewegungen bzw. Rangieren verboten «zu»; Zustimmung zur Rangierbewegung bzw. Rangieren gestattet «offen». Zwerg- und Rangiersignale sind nur bei Rangierbewegungen zu melden. Kontrolllicht zur Bahnübergangsanlage: eingeschaltet / blinkt «Kontrolllicht blinkt»; blinkt nicht «anhalten! - Kontrolllicht dunkel»."
addm("3.2.4","Wer meldet Signale","Wer hat sich gemäss § nebst dem eingeteilten LF die Stellung der Signale zu melden, wenn er im Führerstand ist (Mehrfachauswahl).",["Ein Vorgesetzter","Ein LF in Ausbildung","Ein Führergehilfe","Ein weiterer LF"],["Der ZBE","Der FDL"],F)
add("3.2.4","Meldung Warnung oder Halt","Wie lautet die Meldung gemäss § bei «Warnung» oder «Halt» am Zugsignal?","«zu».",["«offen».","«kurze Fahrt».","«schräg offen»."],F)
add("3.2.4","Meldung Freie Fahrt","Wie lautet die Meldung gemäss § bei «Freie Fahrt» oder «Ankündigung Freie Fahrt» am Zugsignal?","«offen».",["«zu».","«gerade offen».","«kurze Fahrt»."],F)
add("3.2.4","Meldung Geschwindigkeit","Wie lautet die Meldung gemäss § bei einer Geschwindigkeits-Ankündigung oder Geschwindigkeits-Ausführung?","«offen» und die signalisierte Geschwindigkeit bzw. die in der Streckentabelle vorgeschriebene abweichende Geschwindigkeit.",["Nur «offen».","«kurze Fahrt» und die Geschwindigkeit.","«zu» und die Geschwindigkeit."],F)
add("3.2.4","Meldung Kurze Fahrt","Wie lautet die Meldung gemäss § beim Begriff «Kurze Fahrt» am Zugsignal?","«kurze Fahrt».",["«offen».","«zu».","«schräg offen»."],F)
add("3.2.4","Einfahrsignal","Was ist beim Einfahrsignal gemäss § zusätzlich zur Stellung zu melden?","Der Name des betreffenden Bahnhofs.",["Die Gleisnummer.","Die Geschwindigkeit.","Die Zugnummer."],F)
add("3.2.4","Zwergsignal Fahrt","Wie lautet die Meldung gemäss § beim Begriff «Fahrt» am Zwergsignal?","«gerade offen».",["«offen».","«schräg offen».","«zu»."],F)
add("3.2.4","Zwergsignal Fahrt mit Vorsicht","Wie lautet die Meldung gemäss § beim Begriff «Fahrt mit Vorsicht» am Zwergsignal?","«schräg offen».",["«gerade offen».","«offen».","«kurze Fahrt»."],F)
add("3.2.4","Zwergsignal Halt","Wie lautet die Meldung gemäss § beim Begriff «Halt» am Zwergsignal?","«zu».",["«offen».","«gerade offen».","«schräg offen»."],F)
add("3.2.4","Rangiersignal Meldung","Wie lautet die Meldung gemäss § beim Rangiersignal «Zustimmung zur Rangierbewegung bzw. Rangieren gestattet»?","«offen».",["«gerade offen».","«zu».","«schräg offen»."],F)
add("3.2.4","Zwerg und Rangiersignale melden","Wann sind Zwerg- und Rangiersignale gemäss § zu melden?","Nur bei Rangierbewegungen.",["Bei jeder Zugfahrt.","Nur bei Nacht.","Nur im Bahnhof."],F)
add("3.2.4","Kontrolllicht blinkt","Wie lautet die Meldung gemäss §, wenn das Kontrolllicht zur Bahnübergangsanlage blinkt?","«Kontrolllicht blinkt».",["«offen».","«Kontrolllicht dunkel».","«anhalten! - Kontrolllicht blinkt»."],F)
add("3.2.4","Kontrolllicht dunkel","Wie lautet die Meldung gemäss §, wenn das Kontrolllicht zur Bahnübergangsanlage nicht blinkt?","«anhalten! - Kontrolllicht dunkel».",["«Kontrolllicht dunkel».","«zu».","«Kontrolllicht blinkt nicht»."],F)
F="Befinden sich nebst dem eingeteilten LF zusätzlich ein Vorgesetzter, ein LF in Ausbildung, ein Führergehilfe oder ein weiterer LF im Führerstand, hat der eingeteilte LF diese über allfällige Befehle zu verständigen. Nimmt ein Vorgesetzter, ein LF in Ausbildung, ein Führergehilfe oder ein weiterer LF einen Befehl entgegen, leitet er diesen an den eingeteilten LF weiter."
add("3.2.5","Befehle Führerstand","Was hat der eingeteilte LF gemäss § zu tun, wenn weitere Personen im Führerstand sind?","Er hat diese über allfällige Befehle zu verständigen.",["Er hat die Befehle allein zu behalten.","Er hat die Befehle zu übergeben.","Er hat die Befehle zu widerrufen."],F)
add("3.2.5","Befehl entgegengenommen","Was hat eine weitere Person im Führerstand gemäss § zu tun, die einen Befehl entgegennimmt?","Sie leitet diesen an den eingeteilten LF weiter.",["Sie führt den Befehl selbst aus.","Sie wartet auf Anweisung des FDL.","Sie quittiert den Befehl endgültig."],F)
F="Transporte von Waren aller Art im bedienten Führerstand sind nur zugelassen, wenn sie den LF in der Ausübung der Arbeit nicht behindern und der Fluchtweg gewährleistet ist. Nötigenfalls sind die Waren im unbedienten Führerstand zu befördern. Das EVU bezeichnet die in den Führerständen zugelassenen dienstlichen und privaten Warentransporte."
addm("3.2.6","Warentransport Bedingungen","Unter welchen Bedingungen sind Warentransporte im bedienten Führerstand gemäss § zugelassen (Mehrfachauswahl).",["Sie behindern den LF in der Ausübung der Arbeit nicht","Der Fluchtweg ist gewährleistet"],["Der FDL hat zugestimmt","Der ZBE beaufsichtigt die Waren"],F)
add("3.2.6","Warentransport EVU","Wer bezeichnet gemäss § die in den Führerständen zugelassenen dienstlichen und privaten Warentransporte?","Das EVU.",["Die ISB.","Der LF.","Das BAV."],F)
F="Wenn der LF das Triebfahrzeug oder den Steuerwagen verlässt, ist die Feststellbremse anzuziehen. Der LF verständigt den FDL, wenn der LF ausserhalb der erlaubten Pausen oder Arbeitsunterbrechungen das Triebfahrzeug verlässt."
add("3.2.7","Verlassen Triebfahrzeug","Was ist gemäss § beim Verlassen des Triebfahrzeugs oder Steuerwagens zu tun?","Die Feststellbremse ist anzuziehen.",["Die Zugsammelschiene ist auszuschalten.","Der Hauptschalter ist auszuschalten.","Der Führerstand ist abzuschliessen."],F)
add("3.2.7","FDL verständigen","Wann verständigt der LF gemäss § den FDL beim Verlassen des Triebfahrzeugs?","Wenn er ausserhalb der erlaubten Pausen oder Arbeitsunterbrechungen das Triebfahrzeug verlässt.",["Bei jedem Verlassen des Triebfahrzeugs.","Nur bei Dienstende.","Nur auf Verlangen."],F)
add("3.3.1","Fahrweise Grundsatz","Wie hat der LF den Zug gemäss § zu führen?","Sicher, pünktlich und für den Reisenden komfortabel; nach Möglichkeit wirtschaftlich.",["Nur pünktlich, unabhängig vom Komfort.","Möglichst schnell, auch ohne Rücksicht auf Komfort.","Nur wirtschaftlich."],"Der LF hat den Zug sicher, pünktlich und für den Reisenden komfortabel zu führen. Nach Möglichkeit ist wirtschaftlich zu fahren.")
F="Der LF hat während der Fahrt die Aufmerksamkeit auf den Fahrweg bzw. auf die Strecke zu richten. Daneben sind die der Zugführung dienenden Instrumente und Meldeeinrichtungen zu beachten. Sind während der Fahrt Aktivitäten auszuführen, welche die Aufmerksamkeit stören, ist nötigenfalls die Geschwindigkeit zu reduzieren und allenfalls anzuhalten. Verrichtungen und Gespräche, die mit dem Fahrdienst oder der Fahrzeugbedienung nichts zu tun haben, sind verboten. Bevor der LF ein Triebfahrzeug in Bewegung setzt, hat der LF sich soweit als möglich zu überzeugen, dass keine Personen oder Sachen gefährdet werden. Unmittelbar nach Beginn der Fahrt hat der LF den Zug bzw. die Rangierbewegung auf Unregelmässigkeiten zu kontrollieren. Der LF hat nach Möglichkeit darauf zu achten, dass niemand gefährdet wird. Der LF hat in regelmässigen Abständen und vor der Einfahrt in einen Tunnel den eigenen Zug sowie nach Möglichkeit andere Züge und Rangierbewegungen auf betriebsgefährdende Unregelmässigkeiten zu überwachen."
add("3.3.2","Aufmerksamkeit","Worauf hat der LF während der Fahrt gemäss § die Aufmerksamkeit zu richten?","Auf den Fahrweg bzw. auf die Strecke; daneben auf die der Zugführung dienenden Instrumente und Meldeeinrichtungen.",["Nur auf die Instrumente im Führerstand.","Nur auf die Signale.","Auf Gespräche mit dem Personal."],F)
add("3.3.2","Aktivitäten stören Aufmerksamkeit","Was ist gemäss § zu tun, wenn während der Fahrt Aktivitäten auszuführen sind, welche die Aufmerksamkeit stören?","Nötigenfalls die Geschwindigkeit reduzieren und allenfalls anhalten.",["Die Aktivitäten sind während der Fahrt zu erledigen.","Die Aktivitäten sind an den ZBE zu delegieren.","Die Fahrt ist sofort abzubrechen."],F)
add("3.3.2","Verrichtungen verboten","Was ist gemäss § während der Fahrt verboten?","Verrichtungen und Gespräche, die mit dem Fahrdienst oder der Fahrzeugbedienung nichts zu tun haben.",["Jegliche Gespräche mit dem Führergehilfen.","Der Funkverkehr mit dem FDL.","Das Mitführen von Streckentabellen."],F)
addm("3.3.2","Vor und nach Fahrtbeginn","Was hat der LF gemäss § vor und nach Beginn der Fahrt zu tun (Mehrfachauswahl).",["Sich vor dem In-Bewegung-Setzen soweit möglich überzeugen, dass keine Personen oder Sachen gefährdet werden","Unmittelbar nach Beginn der Fahrt den Zug bzw. die Rangierbewegung auf Unregelmässigkeiten kontrollieren"],["Nach Beginn der Fahrt die Bremsprobe wiederholen","Nach Beginn der Fahrt den FDL über die Abfahrt informieren"],F)
add("3.3.2","Überwachen Tunnel","Wann hat der LF gemäss § den eigenen Zug sowie nach Möglichkeit andere Züge auf betriebsgefährdende Unregelmässigkeiten zu überwachen?","In regelmässigen Abständen und vor der Einfahrt in einen Tunnel.",["Nur nach der Ausfahrt aus einem Tunnel.","Nur bei Dunkelheit.","Nur in Bahnhöfen."],F)
add("3.3.3","Ohne Zustimmung","Wann darf ein Zug oder eine Rangierbewegung gemäss § ohne Zustimmung bzw. Fahrbefehl in Bewegung gesetzt werden?","Nur wenn Gefahr droht.",["Wenn der LF die Strecke kennt.","Wenn der Fahrplan es vorsieht.","Wenn der ZBE zustimmt."],"Ein Zug oder eine Rangierbewegung darf ohne Zustimmung bzw. Fahrbefehl nur in Bewegung gesetzt werden, wenn Gefahr droht.")
F="Sind die Lichter zur Kennzeichnung der Zugspitze zusätzlich mit Scheinwerfern ausgerüstet, müssen diese so bedient werden, dass niemand unnötig geblendet wird. Das Sanden ist nach Möglichkeit zu vermeiden: bei Fahrt über Weichen und Kreuzungen; bei Geschwindigkeiten unter 20 km/h und im Stillstand ausser zum Losfahren. Die missbräuchliche Verwendung der Lokpfeife ist zu unterlassen."
add("3.3.4","Scheinwerfer","Wie müssen Scheinwerfer zur Kennzeichnung der Zugspitze gemäss § bedient werden?","So, dass niemand unnötig geblendet wird.",["Immer mit Fernlicht.","Nur bei Dunkelheit.","Dauernd ausgeschaltet."],F)
addm("3.3.4","Sanden vermeiden","Wann ist das Sanden gemäss § nach Möglichkeit zu vermeiden (Mehrfachauswahl).",["Bei Fahrt über Weichen und Kreuzungen","Bei Geschwindigkeiten unter 20 km/h","Im Stillstand, ausser zum Losfahren"],["Bei Fahrt im Tunnel","Bei Geschwindigkeiten über 80 km/h"],F)
add("3.3.4","Lokpfeife","Was ist gemäss § bezüglich der Lokpfeife zu unterlassen?","Die missbräuchliche Verwendung.",["Jede Verwendung im Bahnhof.","Jede Verwendung bei Nacht.","Die Verwendung vor Bahnübergängen."],F)
add("3.3.5","Überschreitung 10 Prozent","Wann ist der LF des vordersten Triebfahrzeugs gemäss § auf eine Überschreitung aufmerksam zu machen?","Bei einer Überschreitung der erlaubten Höchstgeschwindigkeit um 10 %.",["Bei einer Überschreitung um 5 %.","Bei einer Überschreitung um 20 %.","Bei jeder Überschreitung."],"Bei einer Überschreitung der erlaubten Höchstgeschwindigkeit um 10 % ist der LF des vordersten Triebfahrzeugs auf die Überschreitung aufmerksam zu machen. Nötigenfalls ist die Fahrt anzuhalten.")
F="Stellt der LF Schäden oder Unregelmässigkeiten an Anlagen oder Fahrzeugen fest, hat der LF entsprechende Massnahmen zu treffen. Schäden oder Unregelmässigkeiten sind schriftlich der zuständigen Stelle zu melden. Haben die Schäden oder Unregelmässigkeiten direkten Einfluss auf die bevorstehende Fahrt, sind diese zusätzlich dem FDL zu melden."
add("4.1","Schäden melden","Wie sind Schäden oder Unregelmässigkeiten an Anlagen oder Fahrzeugen gemäss § der zuständigen Stelle zu melden?","Schriftlich.",["Mündlich.","Per Funk.","Nur auf Anfrage."],F)
add("4.1","Zusätzlich FDL","Wann sind Schäden oder Unregelmässigkeiten gemäss § zusätzlich dem FDL zu melden?","Wenn sie direkten Einfluss auf die bevorstehende Fahrt haben.",["Bei jeder Unregelmässigkeit.","Nur bei Beschädigung von Anlagen.","Nur bei Dunkelheit."],F)
F="Bei Verdacht auf schlechte Adhäsionsverhältnisse reduziert der LF von sich aus die Geschwindigkeit, insbesondere beim Befahren von Gefällen. Besteht wegen starkem Schneefall, Schneerutschrisiko oder vereister Spurrillen erhöhte Entgleisungsgefahr, kann der LF eine Vorspannlokomotive anfordern oder das Triebfahrzeug eines Pendelzuges an der Zugspitze einreihen lassen."
add("4.2","Schlechte Adhäsion","Was hat der LF gemäss § bei Verdacht auf schlechte Adhäsionsverhältnisse zu tun?","Von sich aus die Geschwindigkeit reduzieren, insbesondere beim Befahren von Gefällen.",["Den FDL um Erlaubnis fragen.","Mit unveränderter Geschwindigkeit weiterfahren.","Sofort anhalten."],F)
addm("4.2","Entgleisungsgefahr","Welche Massnahmen kann der LF gemäss § bei erhöhter Entgleisungsgefahr durch Schneefall, Schneerutschrisiko oder vereiste Spurrillen treffen (Mehrfachauswahl).",["Eine Vorspannlokomotive anfordern","Das Triebfahrzeug eines Pendelzuges an der Zugspitze einreihen lassen"],["Die Geschwindigkeit erhöhen","Die Fahrleitung ausschalten lassen"],F)
